$field=static function(string $key,string $label,int $max=180,string $type='text',bool $required=false)use($values,$donationText):void{ ?><label><?= e($label) ?><?= $required?' *':'' ?><?php if($type==='textarea'): ?><textarea class="form-control" name="<?= e($key) ?>" maxlength="<?= $max ?>" rows="4" <?= $required?'required':'' ?>><?= e($values[$key]) ?></textarea><?php else: ?><input class="form-control" name="<?= e($key) ?>" type="<?= e($type) ?>" maxlength="<?= $max ?>" value="<?= e($values[$key]) ?>" <?= $required?'required':'' ?>><?php endif ?></label><?php };
$select=static function(string $key,string $label,array $options)use($values,$donationText):void{ ?><label><?= e($label) ?><select class="form-control" name="<?= e($key) ?>"><?php foreach($options as $v=>$name): ?><option value="<?= e($v) ?>" <?= $values[$key]===$v?'selected':'' ?>><?= e($name) ?></option><?php endforeach ?></select></label><?php };
